    with urllib.request.build_opener(HTTPSOnly).open(urllib.request.Request(url,headers={'User-Agent':'alirezadns/0.5'}),timeout=45) as r:
        data=r.read(limit+1)
        if len(data)>limit:raise RuntimeError('Download too large')
