#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-or-later
"""Install the independently licensed Mirza application in its own service account.
No shell interpolation, no shared PHP pool, no root bot worker, no DB deletion.
"""
import signal,time,fcntl,base64,hashlib,json,os,pathlib,pwd,secrets,shutil,subprocess,sys,tarfile,tempfile
APP=pathlib.Path('/opt/alirezabot'); STATE=pathlib.Path('/var/lib/alirezabot'); HERE=pathlib.Path(__file__).resolve().parent
UNITS=['alirezabot-php.service','alirezabot-poller.service','alirezabot-maintenance.timer']
def run(args,data=None,timeout=180):
    with subprocess.Popen(args,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True) as child:
        try:out,_=child.communicate(data,timeout=timeout)
        except subprocess.TimeoutExpired:
            try:os.killpg(child.pid,signal.SIGTERM)
            except ProcessLookupError:pass
            try:child.communicate(timeout=5)
            except subprocess.TimeoutExpired:
                try:os.killpg(child.pid,signal.SIGKILL)
                except ProcessLookupError:pass
                child.communicate()
            raise RuntimeError('COMMAND_TIMEOUT:'+pathlib.Path(args[0]).name)
        if child.returncode:raise RuntimeError('COMMAND_FAILED:'+pathlib.Path(args[0]).name)
        return out

def status():
    output=subprocess.run(['systemctl','show','--property=Id,ActiveState',*UNITS],capture_output=True,text=True,timeout=10).stdout
    active={u:'unknown' for u in UNITS}
    for block in output.split('\n\n'):
        values=dict(line.split('=',1) for line in block.splitlines() if '=' in line)
        if values.get('Id') in active:active[values['Id']]=values.get('ActiveState','unknown')
    inbox={'failed':0,'uncertain':0,'processing':0}
    for p in (STATE/'inbox').glob('*.json'):
        try:kind=json.loads(p.read_text()).get('status');inbox[kind]=inbox.get(kind,0)+1
        except (OSError,ValueError):inbox['uncertain']+=1
    try:telegram=json.loads((STATE/'telegram-health.json').read_text())
    except (FileNotFoundError,ValueError):telegram={}
    telegram={k:telegram[k] for k in ['connected','lastPoll','errorCode'] if k in telegram}
    telegram['connected']=telegram.get('connected') is True and time.time()-telegram.get('lastPoll',0)<90 and active.get('alirezabot-poller.service')=='active'
    metrics={'users':None,'invoices':None}
    if (APP/'config.php').exists():
        try:
            script="chdir('/opt/alirezabot');require 'config.php';echo json_encode(['users'=>(int)$pdo->query('SELECT COUNT(*) FROM user')->fetchColumn(),'invoices'=>(int)$pdo->query('SELECT COUNT(*) FROM invoice')->fetchColumn()]);"
            metrics=json.loads(run(['php','-r',script],timeout=5))
        except (RuntimeError,ValueError,OSError):pass
    return {'metrics':metrics,'telegram':telegram,'inbox':inbox,'installed':(APP/'config.php').exists(),'services':active,'running':all(v=='active' for v in active.values())}
def phpvalue(v):return "'"+str(v).replace('\\','\\\\').replace("'","\\'")+"'"
def php_fpm():
    php_version=run(['php','-r','echo PHP_MAJOR_VERSION.".".PHP_MINOR_VERSION;'],timeout=15).strip()
    fpm=pathlib.Path('/usr/sbin')/('php-fpm'+php_version)
    if not fpm.is_file():raise RuntimeError('BOT_MATCHING_PHP_FPM_MISSING')
    return fpm
def install(v):
    if os.geteuid()!=0:raise RuntimeError('ROOT_REQUIRED')
    if (APP/'config.php').exists() and not(APP/'.alirezaserver-managed').exists():raise RuntimeError('EXISTING_BOT_DIRECTORY_CONFLICT')
    old_fpm={p.name for d in ['/lib/systemd/system','/usr/lib/systemd/system','/etc/systemd/system'] for p in pathlib.Path(d).glob('php*-fpm.service')}
    extensions_ok=False
    if shutil.which('php'):
        extensions_ok=subprocess.run(['php','-r',"exit(count(array_diff(['pdo_mysql','curl','mbstring','zip','gd','dom','bcmath'],get_loaded_extensions()))?1:0);"],capture_output=True,timeout=15).returncode==0
    if not extensions_ok or not shutil.which('php') or not any(pathlib.Path('/usr/sbin').glob('php-fpm*')) or not shutil.which('mariadb') or not shutil.which('logrotate'):
        run(['apt-get','update'],timeout=180);run(['apt-get','install','-y','php-cli','php-fpm','php-mysql','php-curl','php-mbstring','php-zip','php-gd','php-xml','php-bcmath','mariadb-server','logrotate'],timeout=600)
    if int(run(['php','-r','echo PHP_VERSION_ID;'],timeout=15).strip())<80200:raise RuntimeError('BOT_REQUIRES_PHP_82_OR_NEWER')
    fpm=php_fpm()
    # Disable only distribution PHP pools newly introduced by this installation.
    for d in ['/lib/systemd/system','/usr/lib/systemd/system']:
        for unit in pathlib.Path(d).glob('php*-fpm.service'):
            if unit.name not in old_fpm:run(['systemctl','disable','--now',unit.name],timeout=30)
    run(['systemctl','start','mariadb'],timeout=30)
    try:pwd.getpwnam('alirezabot')
    except KeyError:run(['useradd','--system','--home-dir',str(STATE),'--shell','/usr/sbin/nologin','alirezabot'])
    STATE.mkdir(mode=0o750,parents=True,exist_ok=True); APP.mkdir(mode=0o750,parents=True,exist_ok=True)
    payload=base64.b64decode((HERE/'alirezabot-source.tar.b64').read_bytes(),validate=False)
    manifest=json.loads((HERE/'reference-versions.json').read_text())
    if hashlib.sha256(payload).hexdigest()!=manifest['bot']['packagedSHA256']:raise RuntimeError('BOT_PAYLOAD_CHECKSUM')
    with tempfile.TemporaryDirectory() as temp:
        arc=pathlib.Path(temp)/'bot.tgz';arc.write_bytes(payload)
        with tarfile.open(arc) as tar:
            for m in tar.getmembers():
                if m.name.startswith('/') or '..' in pathlib.PurePosixPath(m.name).parts or not(m.isfile() or m.isdir()):raise RuntimeError('UNSAFE_BOT_ARCHIVE')
            tar.extractall(APP,filter='data')
