        if run(['mariadb','--protocol=socket','-u','root','-N','-e',"SHOW DATABASES LIKE 'alirezabot'"]).strip():raise RuntimeError('EXISTING_BOT_DATABASE_CONFLICT')
        (APP/'.alirezaserver-managed').write_text('alirezaserver managed Mirza installation\n')
        os.chmod(APP/'.alirezaserver-managed',0o600)
    sql="CREATE DATABASE IF NOT EXISTS alirezabot CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; CREATE USER IF NOT EXISTS 'alirezabot'@'localhost' IDENTIFIED BY '"+dbpass+"'; GRANT ALL ON alirezabot.* TO 'alirezabot'@'localhost';"
    run(['mariadb','--protocol=socket','-u','root'],sql)
    config='''<?php
$request_exec_timeout = 30000;
$dbhost='localhost';$dbname='alirezabot';$usernamedb='alirezabot';
$passworddb=DBPASSWORD;
$pdo=new PDO('mysql:host=localhost;dbname=alirezabot;charset=utf8mb4',$usernamedb,$passworddb,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
$APIKEY=BOTTOKEN;$adminnumber=ADMINID;$domainhosts=DOMAIN;$usernamebot=BOTNAME;
'''
    for k,value in {'DBPASSWORD':dbpass,'BOTTOKEN':v['token'],'ADMINID':v['adminId'],'DOMAIN':v['domain'],'BOTNAME':v['username']}.items():config=config.replace(k,phpvalue(value))
    (APP/'config.php').write_text(config);os.chmod(APP/'config.php',0o640)
    run(['php','-r',"chdir('/opt/alirezabot');require 'db/bootstrap.php';"],timeout=120)
    if v.get('resetWebPassword'):
        script="require '/opt/alirezabot/config.php';$v=json_decode(stream_get_contents(STDIN),true);$q=$pdo->prepare('UPDATE admin SET username=?,password=?,rule=? WHERE id_admin=?');$q->execute(['admin',password_hash($v['password'],PASSWORD_DEFAULT),'administrator',$v['id']]);"
        run(['php','-r',script],json.dumps({'password':v['webPassword'],'id':v['adminId']}))
    # Register a scoped compatibility connection, preserving existing prices/plans.
    if v.get('bridgeURL'):
        script="""require '/opt/alirezabot/config.php';$v=json_decode(stream_get_contents(STDIN),true);$q=$pdo->prepare('SELECT id FROM marzban_panel WHERE code_panel=?');$q->execute(['alirezaserver-local']);$id=$q->fetchColumn();if(!$id){$q=$pdo->prepare("INSERT INTO marzban_panel (code_panel,name_panel,type,status,on_hold_test,version_panel,conecton) VALUES (?,?,?,'active','0','0','offconecton')");$q->execute(['alirezaserver-local','alirezaserver','x-ui_single']);$id=$pdo->lastInsertId();}$q=$pdo->prepare('UPDATE marzban_panel SET url_panel=?,password_panel=?,linksubx=?,inbounds=? WHERE id=?');$q->execute([$v['url'],$v['token'],$v['sub'],json_encode($v['inbounds']),$id]);"""
        run(['php','-r',script],json.dumps({'url':v['bridgeURL'],'token':v['bridgeToken'],'sub':v['subscriptionURL'],'inbounds':v.get('inboundIds',[])}))
    shutil.chown(APP,user='alirezabot',group='alirezabot');shutil.chown(STATE,user='alirezabot',group='alirezabot')
    for path in APP.rglob('*'):
        if path.is_symlink():raise RuntimeError('BOT_SYMLINK_REFUSED')
        shutil.chown(path,user='alirezabot',group='alirezabot')
        if path.is_file():os.chmod(path,0o640)
        elif path.is_dir():os.chmod(path,0o750)
    config='''[global]
pid=/run/alirezabot/php.pid
error_log=/proc/self/fd/2
daemonize=no
[alirezabot]
user=alirezabot
group=alirezabot
listen=/run/alirezabot/php.sock
listen.mode=0660
listen.owner=root
listen.group=root
pm=ondemand
pm.max_children=3
pm.process_idle_timeout=10s
pm.max_requests=300
clear_env=yes
catch_workers_output=yes
security.limit_extensions=.php
php_admin_flag[display_errors]=off
php_admin_flag[log_errors]=on
php_admin_value[error_log]=/proc/self/fd/2
php_admin_value[memory_limit]=192M
php_admin_value[session.save_path]=/var/lib/alirezabot
php_admin_value[opcache.enable]=1
php_admin_value[opcache.memory_consumption]=32
'''
    (APP/'php-fpm.conf').write_text(config)
    common='''After=network-online.target mariadb.service
[Service]
Restart=on-failure
RestartSec=5
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=strict
ProtectHome=true
ReadWritePaths=/opt/alirezabot /var/lib/alirezabot
UMask=0027
StandardOutput=journal
StandardError=journal
LogRateLimitIntervalSec=30s
LogRateLimitBurst=200
'''
    web='[Unit]\nDescription=alirezabot dedicated PHP FastCGI\n'+common+'RuntimeDirectory=alirezabot\nExecStart='+str(fpm)+' --nodaemonize --fpm-config /opt/alirezabot/php-fpm.conf\n[Install]\nWantedBy=multi-user.target\n'
    poll='[Unit]\nDescription=alirezabot Telegram polling\n'+common+'User=alirezabot\nGroup=alirezabot\nWorkingDirectory=/opt/alirezabot\nExecStart=/usr/bin/php /opt/alirezabot/poll.php\n[Install]\nWantedBy=multi-user.target\n'
    for name,content in zip(UNITS,[web,poll]):pathlib.Path('/etc/systemd/system',name).write_text(content)
    maintenance='[Unit]\nDescription=alirezabot scheduled tasks\n'+common+'Type=oneshot\nUser=alirezabot\nGroup=alirezabot\nWorkingDirectory=/opt/alirezabot\nExecStart=/usr/bin/php /opt/alirezabot/cronbot/run.php\n'
    pathlib.Path('/etc/systemd/system/alirezabot-maintenance.service').write_text(maintenance)
    pathlib.Path('/etc/systemd/system/alirezabot-maintenance.timer').write_text('[Unit]\nDescription=alirezabot minute dispatcher\n[Timer]\nOnCalendar=*-*-* *:*:00\nPersistent=true\nRandomizedDelaySec=5\nUnit=alirezabot-maintenance.service\n[Install]\nWantedBy=timers.target\n')
    pathlib.Path('/etc/logrotate.d').mkdir(parents=True,exist_ok=True)
    pathlib.Path('/etc/logrotate.d/alirezabot').write_text('/opt/alirezabot/error_log /opt/alirezabot/panel/error_log /opt/alirezabot/cronbot/error_log /opt/alirezabot/storage/log.txt /opt/alirezabot/*.log /opt/alirezabot/log/*.log /opt/alirezabot/storage/logs/*.log {\n weekly\n rotate 4\n size 5M\n missingok\n notifempty\n compress\n delaycompress\n copytruncate\n su alirezabot alirezabot\n}\n')
    run([str(fpm),'--test','--fpm-config',str(APP/'php-fpm.conf')],timeout=15)
    run(['systemctl','daemon-reload']);run(['systemctl','enable','--now',*UNITS],timeout=30);run(['systemctl','restart',*UNITS],timeout=30)
