/* SPDX-License-Identifier: GPL-3.0-or-later */
(()=>{'use strict';const base=(window.__NOVA_BASE__||'')+'/alireza/',fa=()=>document.documentElement.lang==='fa'||document.documentElement.dir==='rtl',tr=(f,e)=>fa()?f:e;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 async function api(path,method='GET',data){const r=await fetch(base+'api/bot/'+path,{method,credentials:'same-origin',headers:data?{'content-type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const j=await r.json();if(!r.ok)throw Error(j.error||'BOT_FAILED');return j;}
 window.alirezaBot=async()=>{if(typeof isOwner!=='function'||!isOwner())return;const defaultDomain=location.host+base+'bot/web';const modal=window.AlirezaUI.page('Alirezabot · Telegram',`<div class="azbot"><div class="az-host-summary" data-metrics></div><div class="prof-sec"><div class="between"><strong data-status>${esc(tr('در حال بررسی…','Checking…'))}</strong><button class="btn" data-refresh>${esc(tr('تازه‌سازی','Refresh'))}</button></div><p class="az-manual-note">${esc(tr('خود ربات و رابط وب کامل Mirza با نام alirezabot؛ ظاهر وب مستقل حفظ شده است. PHP و MariaDB فقط با اقدام شما نصب می‌شوند.','The complete Mirza bot and original web interface, branded alirezabot. PHP and MariaDB are installed only when you choose Install.'))}</p><a class="btn primary" target="_blank" rel="noopener noreferrer" href="${esc(base+'bot/web/panel/')}" data-open>${esc(tr('بازکردن پنل کامل ربات','Open full bot web panel'))}</a></div><form data-form class="prof-sec"><div class="azm-grid"><div class="field"><label>Bot token</label><input class="input" name="token" dir="ltr" type="password" autocomplete="new-password" required></div><div class="field"><label>Admin Chat ID</label><input class="input" name="adminId" dir="ltr" inputmode="numeric" required></div><div class="field"><label>${esc(tr('آدرس عمومی ربات، با مسیر کامل','Public bot address, including full path'))}</label><input class="input" name="domain" dir="ltr" value="${esc(defaultDomain)}" required></div></div><label><input name="resetWebPassword" type="checkbox"> ${esc(tr('بازنشانی رمز پنل مستقل ربات','Reset bot web panel password'))}</label><p class="az-manual-note">${esc(tr('رمز فقط یک بار پس از نصب یا بازنشانی نمایش داده می‌شود. نصب مجدد حساب‌ها، قیمت‌ها و تنظیمات دیتابیس را حذف نمی‌کند.','The password is shown once after installation or reset. Reinstall preserves accounts, prices and database settings.'))}</p><button class="btn primary" type="submit">${esc(tr('نصب / ذخیره و راه‌اندازی','Install / save and start'))}</button></form><div class="az-manual-actions">${[['start','شروع','Start'],['stop','توقف','Stop'],['restart','راه‌اندازی مجدد','Restart'],['retry-failed','تلاش مجدد پیام‌های بررسی‌شده (۳ مورد)','Retry reviewed messages (up to 3)'],['uninstall','حذف سرویس با حفظ داده‌ها','Remove services, retain data']].map(([a,f,e])=>`<button class="btn" data-action="${a}">${esc(tr(f,e))}</button>`).join('')}</div><p data-inbox></p><div class="notice plain" data-progress role="status"></div><div class="field-err show" data-error role="alert"></div><div data-credentials hidden><p>${esc(tr('اطلاعات ورود؛ همین حالا در جای امن ذخیره کنید','Login details: save securely now'))}</p><input class="input" value="admin" readonly><input class="input" data-password type="password" readonly dir="ltr"><button class="btn" data-reveal>${esc(tr('نمایش / پنهان','Show / hide'))}</button></div></div>`);if(!modal)return;const root=modal.querySelector('.azbot'),form=root.querySelector('form'),error=root.querySelector('[data-error]'),progress=root.querySelector('[data-progress]');let busy=false;
