#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-or-later
"""Hashem adapter: private paths, fixed downloads, argument arrays, owned-service guard."""
import shlex,fcntl,gzip,io,base64,hashlib,ipaddress,json,os,pathlib,re,shutil,signal,subprocess,sys,tarfile,tempfile,time,urllib.request
HERE=pathlib.Path(__file__).resolve().parent; ROOT=pathlib.Path('/var/lib/alirezaserver/hashem'); APP=pathlib.Path('/opt/alirezaserver-hashem'); CFG=pathlib.Path('/etc/alirezaserver-hashem')
UNITS=['alireza-hashem-'+n for n in ['frps','frpc','frps-wss','backhaul-server','backhaul-client','az-hashem-gre','hashem-watchdog','carrier']]
SYSTEMD=pathlib.Path('/etc/systemd/system')
MARKER='# alirezaserver-hashem-managed\n'
UNIT_FILES=[n+'.service' for n in UNITS]+['alireza-hashem-hashem-watchdog.timer']
def run(args,timeout=60):
 r=subprocess.run(args,capture_output=True,text=True,timeout=timeout)
 if r.returncode:raise RuntimeError('HASHEM_COMMAND_FAILED:'+pathlib.Path(args[0]).name)
 return r.stdout

def config(v):
 role=v.get('role');engine=v.get('engine','gre');transport=v.get('transport','tcp');carrier=v.get('carrier','direct')
 if role not in ['iran','foreign'] or engine not in ['gre','backhaul','gre-backhaul']:raise RuntimeError('INVALID_TUNNEL_ROLE_OR_ENGINE')
 for k in ['localPub','remotePub']:
  try:ip=ipaddress.ip_address(v.get(k,''))
  except ValueError:raise RuntimeError('INVALID_'+k)
  if ip.version!=4 or ip.is_loopback or ip.is_multicast or ip.is_unspecified:raise RuntimeError('IPV4_REQUIRED_'+k)
 if v['localPub']==v['remotePub']:raise RuntimeError('TUNNEL_ENDPOINTS_MUST_DIFFER')
 allowed=['tcp','kcp','quic','websocket','wss'] if engine=='gre' else ['tcp','tcpmux','ws','wss','wsmux','wssmux']
 if transport not in allowed or not (carrier in ['direct','auto'] or re.fullmatch(r'(fou|wss):([1-9][0-9]{0,4})',carrier)):raise RuntimeError('INVALID_TRANSPORT_OR_CARRIER')
 port=int(v.get('port',3080));ports=sorted(set(int(str(p).strip()) for p in (v.get('ports',[]) if isinstance(v.get('ports'),list) else str(v.get('ports','')).split(',')) if str(p).strip()))
 if not 1<=port<65535 or not ports or any(p<1 or p>65535 for p in ports):raise RuntimeError('INVALID_PORTS')
 token=str(v.get('token',''))
 if not re.fullmatch(r'[A-Za-z0-9_-]{24,128}',token):raise RuntimeError('INVALID_TUNNEL_TOKEN')
 if engine=='backhaul' and carrier!='direct':raise RuntimeError('CARRIER_REQUIRES_GRE_ENGINE')
