                    R_POOL=${R_POOL:-5}
                    cli_bagher enable --remote-host "$R_IP" --ssh-port "$R_PORT" --ports "$R_PORTS" --mode bagher --pool-count "$R_POOL"
                fi
                pause_prompt
                ;;
