        cp -f "${INSTALL_DIR}/backhaul" "/root/backhaul-core/backhaul_premium" 2>/dev/null || ln -sf "${INSTALL_DIR}/backhaul" "/root/backhaul-core/backhaul_premium"
        chmod +x "/root/backhaul-core/backhaul_premium" 2>/dev/null || true
    fi
